import{_ as a,C as i,o as r,c as n,E as o,a2 as s}from"./chunks/framework.BOeh4kYD.js";const b=JSON.parse('{"title":"Memory Still Exists; That Does Not Make It Inheritable","description":"","frontmatter":{"title":"Memory Still Exists; That Does Not Make It Inheritable","date":"2026-09-08","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当数字员工更换模型、读写方式或嵌入模型后，需要哪些证据，才能让原有持久记忆成为新运行环境的权威记忆？","summary":"A controlled study shows that intact files, readable formats, and matching vector dimensions do not guarantee that a changed model stack will retrieve and interpret old memory consistently. Robust upgrades should separate storage integrity, semantic compatibility, recoverability, and activation authority.","sources":["research/analysis/Q-20260908-01-memory-migration-admission.md"],"item_id":"Q-20260908-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-08-memory-must-be-readmitted-editorial-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-09-08-memory-must-be-readmitted.md","filePath":"en/digital-employee/2026-09-08-memory-must-be-readmitted.md","lastUpdated":1788926442000}'),d={name:"en/digital-employee/2026-09-08-memory-must-be-readmitted.md"};function l(c,e,m,h,p,u){const t=i("ArticleCover");return r(),n("div",null,[o(t,{image:"/assets/covers/daily-2026-09-08-memory-must-be-readmitted-editorial-v2.webp",kicker:"Digital Employee · Daily Research",title:"Memory Still Exists; That Does Not Make It Inheritable",summary:"A controlled study shows that intact files, readable formats, and matching vector dimensions do not guarantee that a changed model stack will retrieve and interpret old memory consistently. Robust upgrades should separate storage integrity, semantic compatibility, recoverability, and activation authority.",version:"Q-20260908-01",status:"Daily Runtime V5 · 2026-09-08",languageHref:"/zh/digital-employee/2026-09-08-memory-must-be-readmitted",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="memory-still-exists-that-does-not-make-it-inheritable" tabindex="-1">Memory Still Exists; That Does Not Make It Inheritable <a class="header-anchor" href="#memory-still-exists-that-does-not-make-it-inheritable" aria-label="Permalink to &quot;Memory Still Exists; That Does Not Make It Inheritable&quot;">​</a></h1><p>After a model upgrade, a digital employee restarts. The database opens, file hashes are unchanged, and vectors still have 1,024 dimensions. Conventional integrity checks pass, so the system immediately adopts the old memory.</p><p>The hidden problem is that <strong>unchanged bytes do not guarantee that the new stack retrieves and interprets the same meaning.</strong> A controlled study of agent-memory portability reports that moving free-form memory between models can help in one direction and hurt in the reverse direction. Mixing embeddings from two versions with the same dimensionality also fails to reproduce the full benefit of rebuilding the index.</p><p>The core proposition is: <strong>physical persistence, semantic compatibility, recoverability, and activation authority are four distinct states. After a material model, writer, reader, or embedding change, durable memory must be re-admitted before it becomes authoritative for the new runtime.</strong></p><h2 id="byte-continuity-is-not-meaning-continuity" tabindex="-1">Byte Continuity Is Not Meaning Continuity <a class="header-anchor" href="#byte-continuity-is-not-meaning-continuity" aria-label="Permalink to &quot;Byte Continuity Is Not Meaning Continuity&quot;">​</a></h2><p>Storage systems answer deterministic questions well: does the file exist, can the database be parsed, does the record match its schema, and are vector shapes consistent? Those checks matter, but they observe physical form.</p><p>Operational memory also depends on construction, retrieval, and interpretation. A writer decides how facts are compressed. An embedder defines similarity in vector space. A reader turns retrieved material into an answer. A change at any layer can alter the meaning available from physically unchanged data.</p><p>This is not ordinary corruption. The data can remain intact while the semantic contract changes. If a runtime exposes only one “memory available” flag, a storage check silently substitutes for both semantic evidence and an activation decision.</p><h2 id="migration-direction-cannot-be-averaged-away" tabindex="-1">Migration Direction Cannot Be Averaged Away <a class="header-anchor" href="#migration-direction-cannot-be-averaged-away" aria-label="Permalink to &quot;Migration Direction Cannot Be Averaged Away&quot;">​</a></h2><p>The primary study captured by the same-date Research Object compares four memory representations, two writer-reader models, two embedding versions, directional swaps, and several recovery methods.</p><p>Free-form notes show pronounced directionality. The study reports that one cross-model reading direction improves by about 9.91 percentage points relative to the corresponding self-note condition, while the reverse direction declines by about 13.28 points. A symmetric average can cancel improvement and harm, producing a mild-looking number that cannot govern either real migration.</p><p>Embedding migration exposes a similar issue. Both examined embedding versions produce 1,024-dimensional vectors, yet a 50/50 mixed index captures only part of the improvement from full re-embedding. In the reported comparison, full migration exceeds the mixed condition by about 6.95 percentage points.</p><p>These numbers belong to the study&#39;s synthetic workload and model pair; they are not enterprise thresholds. They are sufficient to reject a weaker assumption: shared format or dimensionality alone does not establish semantic compatibility. Admission evidence must bind the exact direction—for example, memory produced by an old writer and embedder being consumed by a new reader and embedder.</p><h2 id="four-states-cannot-be-compressed-into-available" tabindex="-1">Four States Cannot Be Compressed into Available <a class="header-anchor" href="#four-states-cannot-be-compressed-into-available" aria-label="Permalink to &quot;Four States Cannot Be Compressed into Available&quot;">​</a></h2><p>A robust migration record preserves at least four facts.</p><table tabindex="0"><thead><tr><th>State</th><th>Question answered</th><th>What it cannot replace</th></tr></thead><tbody><tr><td>Storage integrity</td><td>Is the representation present, parseable, and well formed?</td><td>Whether the new stack preserves meaning</td></tr><tr><td>Semantic compatibility</td><td>Does this exact migration direction pass source-grounded probes?</td><td>Whether failure can be repaired</td></tr><tr><td>Recoverability</td><td>Is an allowed source retained, and has the repair path been tested?</td><td>Whether activation is authorized</td></tr><tr><td>Activation authority</td><td>May the new runtime use this memory generation after technical and policy checks?</td><td>Technical evidence of compatibility</td></tr></tbody></table><p>A memory generation can therefore be intact but quarantined, recoverable but not yet compatible, or technically compatible but barred by privacy, retention, or authorization policy. Explicit states prevent deterministic infrastructure from making semantic and governance decisions it cannot observe.</p><h2 id="the-minimum-migration-evidence-packet" tabindex="-1">The Minimum Migration Evidence Packet <a class="header-anchor" href="#the-minimum-migration-evidence-packet" aria-label="Permalink to &quot;The Minimum Migration Evidence Packet&quot;">​</a></h2><p>An auditable migration packet should record more than “upgrade succeeded.” At minimum, it binds:</p><ul><li>the representation, schema version, and memory generation;</li><li>old writer, new reader, and old/new embedder identities;</li><li>the exact migration direction rather than a global compatibility label;</li><li>a fixed source-grounded semantic probe set, thresholds, results, and failures;</li><li>provenance to recoverable source where policy allows retention;</li><li>repair procedure and version, plus results for this direction;</li><li>the owner and evidence behind the final activation decision.</li></ul><p>During embedding changes, old and new semantic spaces should be isolated or explicitly versioned unless the mixed construction has been shown fit for its intended use. The study does not establish that every mixed index is invalid. It establishes that matching vector shape is far too weak to authorize one as authoritative memory.</p><h2 id="retaining-raw-history-is-not-a-guaranteed-repair" tabindex="-1">Retaining Raw History Is Not a Guaranteed Repair <a class="header-anchor" href="#retaining-raw-history-is-not-a-guaranteed-repair" aria-label="Permalink to &quot;Retaining Raw History Is Not a Guaranteed Repair&quot;">​</a></h2><p>The study also reports that retained source materially enables several repair paths, and full re-embedding is more consistently recoverable than rewriting free-form notes in its workload. Repair is not automatic, however; outcomes differ across repair models.</p><p>Production systems add boundaries the study does not cover. Privacy, retention, and contractual rules may prohibit indefinite raw-history storage. Enterprise memory also includes credentials, preferences, procedural state, and external records, not only question-answer facts. The supported conclusion is therefore not “retain everything forever.” It is that the system must identify its allowed recovery basis and test whether that basis works for the current migration direction.</p><h2 id="upgrade-completion-needs-a-stronger-definition" tabindex="-1">Upgrade Completion Needs a Stronger Definition <a class="header-anchor" href="#upgrade-completion-needs-a-stronger-definition" aria-label="Permalink to &quot;Upgrade Completion Needs a Stronger Definition&quot;">​</a></h2><p>For a long-lived digital employee, an upgrade should not end when the new process starts or the database opens. A stronger completion condition is: physical data checked, exact migration direction semantically probed, recovery route shown usable, policy gates satisfied, and a separate activation decision issued.</p><p>Compatibility evidence also needs freshness. A material change to the model, prompt, schema, embedder, or retrieval policy can invalidate an earlier conclusion. Evidence should bind a component tuple, not permanently label a directory “compatible.”</p><h2 id="evidence-boundary-and-open-questions" tabindex="-1">Evidence Boundary and Open Questions <a class="header-anchor" href="#evidence-boundary-and-open-questions" aria-label="Permalink to &quot;Evidence Boundary and Open Questions&quot;">​</a></h2><p>The evidence comes from a synthetic workload and a limited model combination. It does not show that fixed-schema knowledge graphs are inherently safe or that free-form memory is generally unreliable. It supplies a migration counterexample and useful diagnostics, not a universal production verdict.</p><p>Open questions include how small a semantic probe suite can remain while detecting harmful directional drift; how to isolate generations during partial migration; how to support privacy-preserving recovery when raw source cannot be retained; which changes should automatically expire activation; and how online degradation can distinguish model, retrieval, and memory-migration failures.</p><p>Until those questions are answered, the strongest default is: <strong>memory may remain durable, but its right to be inherited must be earned again.</strong></p><p><strong>Evidence and source:</strong></p><ul><li><a href="https://arxiv.org/html/2609.05339v1" target="_blank" rel="noreferrer">Primary study of agent-memory portability</a></li></ul>',33))])}const g=a(d,[["render",l]]);export{b as __pageData,g as default};
